{"implementation": "def solve(case):
    edges = case['edges']
    refinement = case['refinement']
    members = {}
    for node, com in refinement.items():
        members.setdefault(com, []).append(node)
    for com in members:
        members[com].sort()
    agg = {}
    for u, v, w in edges:
        cu = refinement[u]
        cv = refinement[v]
        if cu > cv:
            cu, cv = cv, cu
        key = (cu, cv)
        agg[key] = agg.get(key, 0) + w
    aggregate_edges = []
    for (cu, cv), weight in agg.items():
        aggregate_edges.append([cu, cv, weight])
    aggregate_edges.sort(key=lambda x: (x[0], x[1]))
    return {'members': members, 'aggregate_edges': aggregate_edges}"}
